<div class="table-wrap"><table><thead><tr><th>Task</th><th>Status</th><th>Date</th><?php if(session('is_logged_in')): ?><th>Actions</th><?php endif; ?></tr></thead><tbody><?php if(!$tasks): ?><tr><td colspan="4" class="empty">No active tasks found.</td></tr><?php endif; ?><?php foreach($tasks as $task): ?><tr><td><?= esc($task['title']) ?></td><td><span class="badge <?= esc($task['status']) ?>"><?= esc(ucfirst($task['status'])) ?></span></td><td><?= esc(date('M j, Y',strtotime($task['task_date']))) ?></td><?php if(session('is_logged_in')): ?><td><div class="actions"><a href="<?= site_url('tasks/'.$task['id'].'/edit') ?>">Edit</a><form action="<?= site_url('tasks/'.$task['id'].'/archive') ?>" method="post" onsubmit="return confirm('Archive this task?')"><?= csrf_field() ?><button>Archive</button></form></div></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div>
